const e=[{id:"sv-2-441",phase:2,topic:"2.1.1",qtype:"concept",difficulty:2,stem:"Which describes the PRIMARY difference between a fishbone diagram and an FMEA?",options:["The fishbone lists potential causes of one effect; the FMEA rates the risk of each way a step can fail","The fishbone rates severity, occurrence and detection; the FMEA only lists causes by category","The fishbone is used only in Control; the FMEA is used only in Define","The fishbone proves which cause matters most; the FMEA only brainstorms ideas"],answer:0,hint:"Fishbone = generate and organise potential causes. FMEA = rate risk (S × O × D) of failure modes.",steps:[{title:"Key idea",body:"A fishbone is organised brainstorming: it shows **possible** causes of one effect. An FMEA rates each failure mode for severity, occurrence and detection."},{title:"Apply to the stem",body:"So the fishbone feeds causes into the FMEA, and the FMEA adds a risk ranking."},{title:"Eliminate look-alikes",body:"Options that swap the roles or claim proof describe neither tool correctly."}],final:"Fishbone lists causes; FMEA rates risk → answer **A**",whyWrong:["","Incorrect — this reverses the two tools: severity, occurrence and detection ratings belong to the FMEA.","Incorrect — both are Measure-phase tools for finding and prioritising X’s; neither is limited to Define or Control.","Incorrect — neither tool proves causation; proof comes from data analysis in Analyze."],bookRef:"Book pp. 119, 131; Syllabus 2.1.1"},{id:"sv-2-442",phase:2,topic:"2.1.1",qtype:"concept",difficulty:1,stem:"On a fishbone diagram, what do the **major bones** represent?",options:["The verified root causes of the effect","Categories of potential causes, such as Machine or Method","The process outputs that customers receive","The solutions the team plans to implement"],answer:1,hint:"Head = effect (Y). Major bones = categories. Minor bones = individual causes.",steps:[{title:"Key idea",body:"The major bones branch from the spine and carry the **category headings** (for example the 6Ms)."},{title:"Apply to the stem",body:"The detailed causes then hang off each category bone as smaller bones."}],final:"Major bones carry the cause categories → answer **B**",whyWrong:["Incorrect — nothing on a fishbone is verified; root causes are confirmed with data in Analyze.","","Incorrect — outputs (Y’s) are shown on a SIPOC; the fishbone has one effect at its head.","Incorrect — solutions are chosen in Improve; a fishbone records causes, not fixes."],bookRef:"Book p. 584 (glossary); Syllabus 2.1.1"},{id:"sv-2-443",phase:2,topic:"2.1.1",qtype:"concept",difficulty:1,stem:"Which is a purpose of a cause-and-effect (fishbone) diagram?",options:["To rank inputs by their weighted impact on several outputs","To show how long work waits between process steps","To organise a team’s ideas about the potential causes of one effect","To quantify how much variation the measurement system adds"],answer:2,hint:"A fishbone generates and groups ideas about possible causes; it does not measure, rank or time anything.",steps:[{title:"Key idea",body:"The book’s quiz states that the fishbone is used to generate ideas about possible causes of defects."},{title:"Eliminate look-alikes",body:"The other options are the jobs of the X-Y matrix, the value stream map and MSA."}],final:"Fishbone = organised ideas about potential causes → answer **C**",whyWrong:["Incorrect — weighting inputs against several outputs is the purpose of the X-Y matrix.","Incorrect — waiting time and queues between steps are shown on a value stream map.","","Incorrect — measurement variation is quantified by a Gage R&R study (MSA)."],bookRef:"Book p. 234; Syllabus 2.1.1"},{id:"sv-2-444",phase:2,topic:"2.1.1",qtype:"concept",difficulty:2,stem:"How does the book describe the information that team tools such as the fishbone and the X-Y matrix produce?",options:["Verified evidence of cause and effect","Statistical estimates of each input’s effect","Customer requirements converted into CTQs","Organised brainstorming, not real data"],answer:3,hint:"Recall the book’s warning on p. 118 about team-based Measure tools.",steps:[{title:"Key idea",body:"The book warns that these tools are “not real data, this is organised brainstorming”."},{title:"Apply to the stem",body:"Later data analysis may show that a cause the team felt sure about is not important."}],final:"Team tools = organised brainstorming → answer **D**",whyWrong:["Incorrect — the team’s ideas are not evidence; Analyze proves or disproves them with data.","Incorrect — no statistics are calculated; the content is team knowledge and opinion.","Incorrect — converting needs into CTQs is a Define activity (VOC and CTQ tree).",""],bookRef:"Book p. 118; Syllabus 2.1.1"},{id:"sv-2-445",phase:2,topic:"2.1.1",qtype:"concept",difficulty:1,stem:"Which are the three primary sources of X’s named in the book?",options:["Process mapping, fishbone analysis and basic data analysis","Project charter, SIPOC and voice of the customer","Control charts, control plans and audits","Hypothesis tests, regression and designed experiments"],answer:0,hint:"Where does the team first find candidate X’s in Measure? Book p. 118.",steps:[{title:"Key idea",body:"The book lists three sources: **process mapping**, **fishbone analysis** and **basic data analysis** (graphical and statistical)."},{title:"Eliminate look-alikes",body:"The other sets belong to Define, Control or the later Analyze/Improve toolkit."}],final:"Map, fishbone, basic data analysis → answer **A**",whyWrong:["","Incorrect — these are Define tools that scope the project and identify Y’s, not sources of X’s.","Incorrect — these are Control-phase tools for sustaining gains.","Incorrect — these test or optimise X’s later; they are not the primary sources for finding them."],bookRef:"Book p. 118; Syllabus 2.1.1"},{id:"sv-2-446",phase:2,topic:"2.1.1",qtype:"concept",difficulty:1,stem:"On a fishbone, what does an input tagged **C** (controllable) describe?",options:["An input governed by a standardised set of activities","An input that can be adjusted or controlled while the process is running","An input that is too expensive or difficult to control","An input already proven by data to drive the Y"],answer:1,hint:"C = adjustable while running; P = set by a procedure; N = not controlled.",steps:[{title:"Key idea",body:"The book defines controllable inputs as those that can be adjusted or controlled while the process runs, for example speed, feed rate or temperature."},{title:"Eliminate look-alikes",body:"Procedural, noise and critical X are different classes."}],final:"C = adjustable while the process runs → answer **B**",whyWrong:["Incorrect — that is a procedural (P) input, such as an SOP or fixed form.","","Incorrect — that is a noise (N) input.","Incorrect — that is a critical X, which only data in Analyze can confirm."],bookRef:"Book pp. 113–114; Syllabus 2.1.1"},{id:"sv-2-447",phase:2,topic:"2.1.1",qtype:"concept",difficulty:2,stem:"How is the C / P / N classification applied to a completed fishbone?",options:["By ranking each cause from most to least frequent","By giving each cause a severity rating from 1 to 10","By tagging each cause so that it can be routed to the X-Y matrix or the FMEA","By testing each cause for a significant p-value"],answer:2,hint:"The tag decides where each cause goes next.",steps:[{title:"Key idea",body:"Every input is classed controllable, procedural or noise."},{title:"Apply to the stem",body:"Controllable X’s go to the X-Y matrix; procedural and noise X’s go to the FMEA."}],final:"Tag each cause to route it → answer **C**",whyWrong:["Incorrect — ranking by frequency is done with a Pareto chart on real data.","Incorrect — severity ratings are part of the FMEA, not the fishbone tag.","","Incorrect — p-values come from hypothesis tests in Analyze."],bookRef:"Book p. 119; Syllabus 2.1.1"},{id:"sv-2-448",phase:2,topic:"2.1.1",qtype:"concept",difficulty:2,stem:"Why does the book say that breakthrough improvement comes mainly from **controllable** X’s?",options:["Because they are already proven to be root causes","Because they never vary once they are set","Because they are the only inputs recorded in the FMEA","Because they can be adjusted while the process runs, so their settings can be optimised"],answer:3,hint:"What can a team actually change while the process runs?",steps:[{title:"Key idea",body:"A controllable X can be set and adjusted, so the team can find and hold its best setting."},{title:"Apply to the stem",body:"That is why controllable X’s are carried into the X-Y matrix to find the vital few."}],final:"Controllable settings can be optimised → answer **D**",whyWrong:["Incorrect — no X is proven at the fishbone stage; proof comes from Analyze.","Incorrect — even controllable inputs vary naturally within their limits.","Incorrect — the FMEA mainly receives procedural and noise inputs.",""],bookRef:"Book p. 119; Syllabus 2.1.1"},{id:"sv-2-449",phase:2,topic:"2.1.1",qtype:"concept",difficulty:1,stem:"A fishbone for *“Home broadband drops every evening”* lists **“Router firmware has a known memory-leak bug.”** Which 6M bone fits this cause?",options:["Machine","Material","Measurement","Method"],answer:0,hint:"Machine = equipment, tools, systems and their software.",steps:[{title:"Key idea",body:"The Machine bone holds causes in equipment, tools and systems."},{title:"Apply to the stem",body:"Firmware is part of the router, so the cause sits on Machine."}],final:"Firmware bug = Machine → answer **A**",whyWrong:["","Incorrect — Material covers inputs consumed by the process, such as parts or data, not equipment software.","Incorrect — Measurement covers how the Y and X’s are measured and recorded.","Incorrect — Method covers procedures and ways of working, not equipment faults."],bookRef:"Syllabus 2.1.1"},{id:"sv-2-450",phase:2,topic:"2.1.1",qtype:"concept",difficulty:2,stem:"What does the book require of **procedural** inputs found on the fishbone?",options:["That they are optimised with a designed experiment","That they are in total compliance, which may need a measure of effectiveness","That they are treated as noise and left unchanged","That they are weighted 1–10 in the X-Y matrix"],answer:1,hint:"Book p. 119: what must be true of every procedure?",steps:[{title:"Key idea",body:"The book states that all procedures must be in total compliance, which may need an effectiveness measure."},{title:"Apply to the stem",body:"Fixing non-compliance can remove defects and lets the team focus on the controllable X’s."}],final:"Procedures must be in total compliance → answer **B**",whyWrong:["Incorrect — DOE is used to optimise controllable settings, not to check procedures.","","Incorrect — a procedure is not noise; it is a defined activity that can be enforced.","Incorrect — the X-Y matrix is mainly for controllable X’s."],bookRef:"Book p. 119; Syllabus 2.1.1"},{id:"sv-2-451",phase:2,topic:"2.1.1",qtype:"concept",difficulty:3,stem:"An X from the fishbone is later shown to be a **critical X**. What must follow, according to the book?",options:["It is reclassified as noise because it varies","It is removed from the FMEA because it is understood","It must be controlled, so it needs requirements and must be measured","It is moved to the head of the fishbone as the new effect"],answer:2,hint:"If an X is critical, by definition you must control it.",steps:[{title:"Key idea",body:"The book says a critical X must be controlled, so it must have requirements and must be measured."},{title:"Eliminate look-alikes",body:"Reclassifying, removing or moving it would lose control of the input that matters most."}],final:"Critical X → requirements and measurement → answer **C**",whyWrong:["Incorrect — a critical X is the opposite of noise; by definition it must be controlled.","Incorrect — critical X’s stay in the FMEA and control plan to be monitored.","","Incorrect — the head is always the effect (Y), never an X."],bookRef:"Book pp. 113–114; Syllabus 2.1.1"},{id:"sv-2-452",phase:2,topic:"2.1.1",qtype:"concept",difficulty:1,stem:"Which 6M category covers **how the Y and the X’s are measured and recorded**?",options:["Machine","Material","Measurement","Method"],answer:2,hint:"One of the 6Ms is about the data itself.",steps:[{title:"Key idea",body:"The Measurement bone asks how the output and inputs are measured, recorded and reported."},{title:"Apply to the stem",body:"A poor measurement system can create or hide variation in Y, so it is a valid cause category."}],final:"How things are measured = Measurement → answer **C**",whyWrong:["Incorrect — Machine covers equipment, tools and systems used to do the work.","Incorrect — Material covers parts, data and other inputs consumed by the process.","","Incorrect — Method covers procedures and the sequence of work."],bookRef:"Syllabus 2.1.1"},{id:"sv-2-453",phase:2,topic:"2.1.1",qtype:"concept",difficulty:1,stem:"What do the **4Ss** used on some service fishbones stand for?",options:["Surroundings, Suppliers, Systems, Skills","Sort, Set in order, Shine, Standardise","Suppliers, Sources, Specifications, Schedules","Safety, Speed, Service, Satisfaction"],answer:0,hint:"Service variants: 4Ps (Policies, Procedures, People, Plant) and 4Ss.",steps:[{title:"Key idea",body:"A common service category set is the 4Ss: **Surroundings, Suppliers, Systems, Skills**."},{title:"Eliminate look-alikes",body:"Sort/Set in order/Shine/Standardise is 5S, a Lean tool."}],final:"4Ss = Surroundings, Suppliers, Systems, Skills → answer **A**",whyWrong:["","Incorrect — these are the first four steps of 5S workplace organisation.","Incorrect — this is not a recognised fishbone category set.","Incorrect — these are performance themes, not fishbone categories."],bookRef:"Syllabus 2.1.1"},{id:"sv-2-454",phase:2,topic:"2.1.1",qtype:"concept",difficulty:2,stem:"A fishbone for *“Invoices issued with wrong customer details”* lists **“Address data received from the sales system is incomplete.”** Which 6M bone fits BEST?",options:["Machine","Material","Measurement","Method"],answer:1,hint:"Material = inputs consumed by the process, including information and data.",steps:[{title:"Key idea",body:"In transactional processes, data and information received from another step are treated as the process’s material."},{title:"Apply to the stem",body:"Incomplete incoming address data is therefore a Material cause."}],final:"Incoming data = Material → answer **B**",whyWrong:["Incorrect — the cause is the content of the data received, not a fault in equipment or software.","","Incorrect — Measurement is about how the Y or X’s are measured, not the input data used.","Incorrect — Method is about how the work is done, not what arrives as an input."],bookRef:"Syllabus 2.1.1"},{id:"sv-2-455",phase:2,topic:"2.1.1",qtype:"concept",difficulty:3,stem:"Which describes the **“blame stop”** trap when drilling a fishbone branch?",options:["Ending the questioning after exactly five “whys”","Placing a cause on the wrong category bone","Writing a solution instead of a cause on a bone","Ending the questioning at “the engineer made a mistake” instead of asking why the system allowed it"],answer:3,hint:"A person is rarely the root cause; ask what in the system let the error happen.",steps:[{title:"Key idea",body:"“Because someone made a mistake” is rarely a root cause."},{title:"Apply to the stem",body:"Keep asking why the process allowed the mistake (no checklist, no mistake-proofing, no training)."}],final:"Stopping at a person = blame stop → answer **D**",whyWrong:["Incorrect — that is treating the 5 Whys count as a rule; five is only a guideline.","Incorrect — bone placement is a convenience and is not the blame trap.","Incorrect — that is the “solution, not cause” error, a different facilitation fault.",""],bookRef:"Syllabus 2.1.1"},{id:"sv-2-456",phase:2,topic:"2.1.1",qtype:"concept",difficulty:1,stem:"Which describes a **minor bone** on a fishbone diagram?",options:["The category heading such as Method or Material","The effect written at the head of the fish","The horizontal arrow that leads to the head","An individual cause or sub-cause that hangs off a category bone"],answer:3,hint:"Spine → major bones (categories) → minor bones (causes) → smaller bones (sub-causes).",steps:[{title:"Key idea",body:"Minor bones carry the detailed causes found in brainstorming."},{title:"Apply to the stem",body:"Asking “why?” about a cause adds even smaller bones beneath it."}],final:"Minor bone = individual cause → answer **D**",whyWrong:["Incorrect — category headings sit on the major bones.","Incorrect — the effect is at the head, not on a bone.","Incorrect — that arrow is the spine of the diagram.",""],bookRef:"Book p. 584 (glossary); Syllabus 2.1.1"},{id:"sv-2-457",phase:2,topic:"2.1.1",qtype:"concept",difficulty:3,stem:"What is the main **limitation** of a fishbone diagram?",options:["It records team opinion, so it cannot show which causes really affect the Y","It can be used only for manufacturing processes","It limits the team to exactly six categories","It needs a large data sample before it can be drawn"],answer:0,hint:"Fishbone = breadth of ideas, not proof.",steps:[{title:"Key idea",body:"The diagram captures what the team believes could cause the effect."},{title:"Apply to the stem",body:"Opinion is valuable but must be tested with data before any cause is called a root cause."}],final:"Opinion only, no proof → answer **A**",whyWrong:["","Incorrect — service variants such as the 4Ps and 4Ss make it suitable for any process.","Incorrect — categories are prompts; any set that fits the process may be used.","Incorrect — it needs no data; it is built from team knowledge."],bookRef:"Book p. 118; Syllabus 2.1.1"},{id:"sv-2-458",phase:2,topic:"2.1.1",qtype:"concept",difficulty:2,stem:"After a fishbone session, a team has logged a month of failed installations against each cause category. Which tool ranks the categories so that the **vital few** stand out?",options:["Affinity diagram","Cause-and-effect diagram","Pareto chart","Scatter diagram"],answer:2,hint:"Ranking counted categories from largest to smallest = 80/20 tool.",steps:[{title:"Key idea",body:"A Pareto chart orders categories by frequency so the few biggest contributors are visible."},{title:"Apply to the stem",body:"The fishbone provided the categories; the logged counts are real data, so a Pareto chart can rank them."}],final:"Rank counted categories → Pareto → answer **C**",whyWrong:["Incorrect — an affinity diagram groups ideas into themes; it does not rank counts.","Incorrect — the fishbone lists causes but does not rank them by frequency.","","Incorrect — a scatter diagram shows the relationship between two continuous variables."],bookRef:"Syllabus 2.1.1"},{id:"sv-2-459",phase:2,topic:"2.1.1",qtype:"concept",difficulty:3,stem:"How does a fishbone diagram differ from an **affinity diagram**?",options:["A fishbone groups ideas into themes; an affinity diagram ranks the themes by frequency","A fishbone starts from one defined effect and organises its causes; an affinity diagram groups many unstructured ideas into themes","A fishbone requires real data; an affinity diagram uses only opinion","A fishbone is a Control tool; an affinity diagram is a Measure tool"],answer:1,hint:"Fishbone: effect first, then causes. Affinity: many ideas first, themes emerge.",steps:[{title:"Key idea",body:"The fishbone needs an agreed effect at the head and asks “what could cause this?”."},{title:"Apply to the stem",body:"An affinity diagram is used when there is a mass of unstructured ideas and no agreed problem yet."}],final:"Effect-led causes vs bottom-up themes → answer **B**",whyWrong:["Incorrect — an affinity diagram does not rank anything; ranking by frequency is a Pareto chart.","","Incorrect — both are built from team ideas; neither requires data.","Incorrect — the fishbone is a Measure tool; neither is mainly a Control tool."],bookRef:"Syllabus 2.1.1"},{id:"sv-2-460",phase:2,topic:"2.1.1",qtype:"concept",difficulty:2,stem:"On a **4Ps** fishbone for loan approvals, where does the cause **“Credit policy requires director sign-off above a set amount”** belong?",options:["People","Plant","Policies","Procedures"],answer:2,hint:"4Ps: Policies (rules from above), Procedures (how work is done), People, Plant.",steps:[{title:"Key idea",body:"Policies are the rules and decisions set by management."},{title:"Apply to the stem",body:"A sign-off threshold is a management rule, so it sits on Policies."},{title:"Eliminate look-alikes",body:"Procedures would hold the steps staff follow to obtain the sign-off."}],final:"Management rule = Policies → answer **C**",whyWrong:["Incorrect — People covers skills, staffing and workload, not rules set by management.","Incorrect — Plant covers buildings, equipment and systems.","","Incorrect — Procedures covers how the work is done step by step, not the rule set above it."],bookRef:"Syllabus 2.1.1"},{id:"sv-2-461",phase:2,topic:"2.1.1",qtype:"concept",difficulty:1,stem:"On a **4Ps** fishbone for a contact centre, where does the cause **“CRM server freezes during peak hours”** belong?",options:["People","Plant","Policies","Procedures"],answer:1,hint:"Plant (sometimes Place) = buildings, equipment and systems.",steps:[{title:"Key idea",body:"The Plant bone holds causes in buildings, equipment and IT systems."},{title:"Apply to the stem",body:"A freezing CRM server is a system fault, so it sits on Plant."}],final:"System fault = Plant → answer **B**",whyWrong:["Incorrect — People covers skills, staffing and behaviour, not equipment or systems.","","Incorrect — Policies covers rules and decisions set by management.","Incorrect — Procedures covers how the work is carried out."],bookRef:"Syllabus 2.1.1"},{id:"sv-2-462",phase:2,topic:"2.1.1",qtype:"concept",difficulty:1,stem:"A packaging-line fishbone lists **“Sealing-jaw temperature set-point.”** How is this input classified?",options:["Controllable (C)","Critical X (proven)","Noise (N)","Procedural (P)"],answer:0,hint:"Can it be adjusted while the process runs?",steps:[{title:"Key idea",body:"Controllable inputs include speed, feed rate, temperature and pressure (book p. 113)."},{title:"Apply to the stem",body:"A temperature set-point can be changed while the line runs, so it is controllable."}],final:"Set-point = controllable → answer **A**",whyWrong:["","Incorrect — nothing on a fishbone is proven; critical status needs data from Analyze.","Incorrect — a set-point can be adjusted while the line runs, so it is not noise.","Incorrect — it is a machine setting, not a standardised set of activities."],bookRef:"Book pp. 113–114; Syllabus 2.1.1"},{id:"sv-2-463",phase:2,topic:"2.1.1",qtype:"concept",difficulty:2,stem:"A fishbone for *“New orders keyed with errors”* lists **“The fixed data-entry form used to log each order.”** How is this input classified?",options:["Controllable (C)","Critical X (proven)","Noise (N)","Procedural (P)"],answer:3,hint:"Book p. 113 lists fixed data-entry forms as an example of one input class.",steps:[{title:"Key idea",body:"Procedural inputs are affected by a standardised set of activities; the book’s examples include material queues, rigging set-up and fixed data-entry forms."},{title:"Apply to the stem",body:"The order-entry form is therefore procedural."}],final:"Fixed form = procedural → answer **D**",whyWrong:["Incorrect — a form is not a setting adjusted while the process runs; it is part of a standard way of working.","Incorrect — no fishbone input is proven; data in Analyze would be needed.","Incorrect — the form is designed and owned by the organisation, so it can be standardised.",""],bookRef:"Book pp. 113–114; Syllabus 2.1.1"},{id:"sv-2-464",phase:2,topic:"2.1.1",qtype:"concept",difficulty:2,stem:"A fishbone for *“Fault calls take too long to diagnose”* lists **“Each caller describes the fault in their own words.”** How is this input classified?",options:["Controllable (C)","Critical X (proven)","Noise (N)","Procedural (P)"],answer:2,hint:"The book lists “the individual” as an example of one input class.",steps:[{title:"Key idea",body:"Noise inputs are those we think we cannot control or that are too costly to control; the book’s examples include the individual."},{title:"Apply to the stem",body:"Individual callers’ descriptions vary outside the team’s control, so they are noise."}],final:"The individual caller = noise → answer **C**",whyWrong:["Incorrect — the team cannot adjust how each individual caller speaks while the process runs.","Incorrect — nothing on a fishbone is proven at this stage.","","Incorrect — the caller’s wording is not governed by the operator’s standard procedure."],bookRef:"Book pp. 113–114; Syllabus 2.1.1"},{id:"sv-2-465",phase:2,topic:"2.1.1",qtype:"concept",difficulty:1,stem:"What is a **potential cause** on a fishbone diagram?",options:["A suspected X recorded by the team that stays a hypothesis until data verify it","A cause confirmed by a significant hypothesis test","A cause with a risk priority number above a threshold","A cause that the sponsor has approved for a solution"],answer:0,hint:"At the Measure stage every cause is “potential”.",steps:[{title:"Key idea",body:"The fishbone records possible X’s from team knowledge."},{title:"Apply to the stem",body:"Each one is a hypothesis; Analyze proves or disproves its impact."}],final:"Potential cause = hypothesis → answer **A**",whyWrong:["","Incorrect — that is a verified cause, established in Analyze, not on the fishbone.","Incorrect — RPNs are calculated in the FMEA, not on the fishbone.","Incorrect — sponsor approval of solutions belongs to Improve."],bookRef:"Book pp. 228, 230; Syllabus 2.1.1"},{id:"sv-2-466",phase:2,topic:"2.1.1",qtype:"concept",difficulty:1,stem:"What is the PRIMARY purpose of drawing **category bones** (such as the 6Ms) before the brainstorm?",options:["To rank the categories by how important they are","To prompt the team to look in every area so that no obvious cause is forgotten","To assign an owner from each department to each bone","To decide which causes are controllable and which are noise"],answer:1,hint:"Categories widen thinking beyond the cause people already “know”.",steps:[{title:"Key idea",body:"Category headings act as prompts."},{title:"Apply to the stem",body:"An empty or thin bone invites the question “have we missed causes here?”."}],final:"Categories prompt broad thinking → answer **B**",whyWrong:["Incorrect — the fishbone does not rank anything; ranking needs data or an X-Y matrix.","","Incorrect — categories are not ownership areas; they are thinking prompts.","Incorrect — C/P/N tagging is a separate step, independent of the bone a cause sits on."],bookRef:"Syllabus 2.1.1"},{id:"sv-2-467",phase:2,topic:"2.1.1",qtype:"concept",difficulty:1,stem:"A fishbone for *“Fibre joints fail the loss test”* lists **“Technician not trained on the new splicing kit.”** Which 6M bone fits this cause?",options:["Machine","Man (People)","Measurement","Method"],answer:1,hint:"Man/People = skills, training, staffing and workload.",steps:[{title:"Key idea",body:"The Man (People) bone holds causes about skills, training and staffing."},{title:"Apply to the stem",body:"Lack of training on the kit is a skills cause."}],final:"Training gap = Man (People) → answer **B**",whyWrong:["Incorrect — the cause is a skills gap in the person, not a fault in the splicing kit itself.","","Incorrect — the cause is not about how loss is measured or recorded.","Incorrect — Method covers the procedure itself, not whether a person is trained on it."],bookRef:"Syllabus 2.1.1"},{id:"sv-2-468",phase:2,topic:"2.1.1",qtype:"concept",difficulty:1,stem:"In $Y = f(X)$ terms, what do the bones of a fishbone diagram hold?",options:["The Y’s that customers care about","The proven transfer function between X and Y","The specification limits for the output","Potential X’s that might drive the effect"],answer:3,hint:"Head = Y; bones = candidate X’s.",steps:[{title:"Key idea",body:"To improve Y the team must find all the X’s that might drive it."},{title:"Apply to the stem",body:"The fishbone puts Y at the head and the potential X’s on the bones."}],final:"Bones = potential X’s → answer **D**",whyWrong:["Incorrect — the Y is the single effect at the head of the fish.","Incorrect — a proven function needs regression or DOE data, not brainstorming.","Incorrect — specification limits come from customer requirements, not the fishbone.",""],bookRef:"Book p. 118; Syllabus 2.1.1"},{id:"sv-2-469",phase:2,topic:"2.1.1",qtype:"concept",difficulty:1,stem:"In which DMAIC phase are the causes listed on a fishbone **proven or disproven** with data?",options:["Analyze","Control","Define","Measure"],answer:0,hint:"Book roadmap: Measure identifies X’s; the next phase proves their impact.",steps:[{title:"Key idea",body:"The roadmap says Measure identifies and prioritises all X’s, and Analyze proves or disproves the impact X’s have on the problem."},{title:"Apply to the stem",body:"So fishbone causes are tested in Analyze."}],final:"Proof of X’s happens in Analyze → answer **A**",whyWrong:["","Incorrect — Control sustains the gains of verified solutions; causes are tested before then.","Incorrect — Define scopes the problem and Y; it does not test X’s.","Incorrect — Measure identifies and prioritises X’s; the roadmap gives the proof step to Analyze."],bookRef:"Book pp. 228, 230; Syllabus 2.1.1"},{id:"sv-2-470",phase:2,topic:"2.1.1",qtype:"concept",difficulty:2,stem:"Which statement about the fishbone diagram is CORRECT?",options:["It ranks causes from the largest to the smallest effect","It proves which causes are statistically significant","It must always use exactly the 6M categories","It identifies potential causes but does not rank them by frequency"],answer:3,hint:"What does the fishbone produce, and what does it not?",steps:[{title:"Key idea",body:"A fishbone gives a categorised list of possible causes."},{title:"Eliminate look-alikes",body:"Ranking, proving and fixed categories are all claims the tool cannot support."}],final:"Lists causes, no ranking → answer **D**",whyWrong:["Incorrect — ranking by size or frequency is done with a Pareto chart or an X-Y matrix.","Incorrect — significance needs hypothesis tests on data in Analyze.","Incorrect — the 6Ms are common, but 4Ps, 4Ss or process steps may be used instead.",""],bookRef:"Syllabus 2.1.1"},{id:"sv-2-471",phase:2,topic:"2.1.1",qtype:"concept",difficulty:2,stem:"Which statement about **controllable** inputs is CORRECT?",options:["A controllable input is held exactly at its set-point at all times","A controllable input is one the team cannot influence","Even a controllable input still varies naturally within its limits","A controllable input must be removed from the X-Y matrix"],answer:2,hint:"Book p. 113: is anything ever completely controlled?",steps:[{title:"Key idea",body:"The book notes that even controllable inputs are never under complete control; they vary within natural limits."},{title:"Apply to the stem",body:"That natural variation is one reason to measure and monitor them."}],final:"Controllable still varies → answer **C**",whyWrong:["Incorrect — the book stresses that no input is ever under complete control.","Incorrect — that describes a noise input.","","Incorrect — controllable inputs are the main rows of the X-Y matrix."],bookRef:"Book pp. 113–114; Syllabus 2.1.1"},{id:"sv-2-472",phase:2,topic:"2.1.1",qtype:"concept",difficulty:2,stem:"Which statement about the **5 Whys** used on a fishbone branch is CORRECT?",options:["The team must ask exactly five questions on every branch","The team stops when it reaches a person who can be held accountable","The team stops when the first answer sounds convincing","Five is a guideline; the team stops when it reaches a cause the process can act on"],answer:3,hint:"When is a branch deep enough?",steps:[{title:"Key idea",body:"Drill each branch until the answer is something the process or organisation could control or change."},{title:"Eliminate look-alikes",body:"A fixed count, a person or the first plausible answer are poor stopping points."}],final:"Stop at an actionable cause → answer **D**",whyWrong:["Incorrect — the number is a rule of thumb, not a requirement.","Incorrect — that is the blame trap; ask why the system allowed the error.","Incorrect — the first answer is usually a symptom one level down.",""],bookRef:"Syllabus 2.1.1"},{id:"sv-2-473",phase:2,topic:"2.1.1",qtype:"concept",difficulty:3,stem:"Which statement about **placing causes on bones** is CORRECT?",options:["Placement is a convenience, so the team should not spend long arguing which bone a cause belongs on","A cause placed on the wrong bone makes the whole diagram invalid","Each cause must be voted on before it can be placed","The bone a cause sits on decides whether it goes to the X-Y matrix"],answer:0,hint:"Categories help thinking; they are not a classification test.",steps:[{title:"Key idea",body:"The purpose of the bones is to prompt ideas, not to classify causes perfectly."},{title:"Apply to the stem",body:"If a cause fits two bones, place it once and move on; the C/P/N tag drives routing."}],final:"Placement is only a convenience → answer **A**",whyWrong:["","Incorrect — bones are prompts; a cause on a different bone is still captured.","Incorrect — voting during generation slows ideas and breaks the no-judgement rule.","Incorrect — routing is decided by the C/P/N tag, not the category bone."],bookRef:"Syllabus 2.1.1"},{id:"sv-2-474",phase:2,topic:"2.1.1",qtype:"concept",difficulty:1,stem:"Which statement about **silent brainstorming** at the start of a fishbone session is CORRECT?",options:["It removes the need for a cross-functional team","It stops the loudest or most senior person from steering the list of causes","It is used to vote for the root cause before the diagram is drawn","It makes sure every cause is verified before it is written down"],answer:1,hint:"Why write alone for a few minutes before discussing?",steps:[{title:"Key idea",body:"Each person writes one cause per note in silence."},{title:"Apply to the stem",body:"This collects everyone’s ideas before discussion lets dominant voices take over."}],final:"Silent writing protects against dominant voices → answer **B**",whyWrong:["Incorrect — silent writing is done by the team; it does not replace it.","","Incorrect — no root cause is chosen at this stage; ideas are only generated.","Incorrect — verification needs data in Analyze, not silent writing."],bookRef:"Syllabus 2.1.1"},{id:"sv-2-475",phase:2,topic:"2.1.1",qtype:"concept",difficulty:2,stem:"Which statement about the **5 Whys and the fishbone** is CORRECT?",options:["The 5 Whys replaces the need for category bones","The fishbone follows only a single chain of cause and effect","The 5 Whys can be used inside a fishbone to add deeper sub-causes on each branch","The 5 Whys may be used only in the Control phase"],answer:2,hint:"Fishbone = breadth; 5 Whys = depth.",steps:[{title:"Key idea",body:"Categories make the diagram wide; repeated “why?” makes each branch deep."},{title:"Apply to the stem",body:"Each answer to “why?” becomes a smaller bone under the cause."}],final:"Whys deepen the branches → answer **C**",whyWrong:["Incorrect — the categories widen the search; the 5 Whys deepens it. They work together.","Incorrect — a single chain is the 5 Whys on its own; a fishbone shows many causes.","","Incorrect — it is a cause-finding technique used while building the fishbone in Measure."],bookRef:"Syllabus 2.1.1"},{id:"sv-2-476",phase:2,topic:"2.1.1",qtype:"concept",difficulty:3,stem:"Which statement about the fishbone’s place in the Measure roadmap is CORRECT?",options:["It follows the capability study and explains the Cpk value","It replaces the X-Y matrix when the team is small","It is completed in Control to monitor the critical X’s","It follows detailed process mapping and comes before the X-Y matrix and FMEA select the vital few"],answer:3,hint:"Roadmap: process map → identify all X’s → select vital few → MSA → stability → capability.",steps:[{title:"Key idea",body:"The book’s Measure roadmap places “identify all process X’s (fishbone, process map)” after detailed process mapping."},{title:"Apply to the stem",body:"The X-Y matrix and FMEA then select the vital few X’s."}],final:"Map → fishbone → X-Y/FMEA → answer **D**",whyWrong:["Incorrect — capability is assessed after the X’s are identified and the measurement system is checked.","Incorrect — the fishbone generates X’s; the X-Y matrix prioritises them. One does not replace the other.","Incorrect — monitoring critical X’s is done with control charts and the control plan.",""],bookRef:"Book pp. 228, 230; Syllabus 2.1.1"},{id:"sv-2-477",phase:2,topic:"2.1.1",qtype:"concept",difficulty:3,stem:"Which statement about the book’s **burnt-pizza** example is CORRECT?",options:["The recipe SOP is an example of a procedural input","Room temperature is an example of a controllable input","Oven temperature is an example of a noise input","Ingredient variation is an example of a procedural input"],answer:0,hint:"Pizza example (p. 114): oven temperature and bake time C; recipe SOP P; room temperature and ingredient variation N.",steps:[{title:"Key idea",body:"In the pizza example, oven temperature and bake time are controllable, the recipe SOP is procedural, and room temperature and ingredient variation are noise."},{title:"Eliminate look-alikes",body:"Each wrong option swaps one input into the wrong class."}],final:"Recipe SOP = procedural → answer **A**",whyWrong:["","Incorrect — the book gives room temperature as a noise input.","Incorrect — oven temperature can be set while baking, so it is controllable.","Incorrect — the book gives ingredient variation as a noise input."],bookRef:"Book pp. 113–114; Syllabus 2.1.1"},{id:"sv-2-478",phase:2,topic:"2.1.1",qtype:"concept",difficulty:3,stem:"Which statement about an **empty bone** on a team’s fishbone is CORRECT?",options:["It proves that the category has no effect on the Y","It is a prompt to ask whether causes in that category have been missed","It shows that every bone must hold the same number of causes","It should be deleted so the diagram looks tidier"],answer:1,hint:"An empty bone is a question, not an answer.",steps:[{title:"Key idea",body:"Checking the balance of the diagram is part of facilitation."},{title:"Apply to the stem",body:"Ask: “Nothing at all under Measurement?” — the gap often hides real causes."}],final:"Empty bone = prompt → answer **B**",whyWrong:["Incorrect — an empty bone shows only that no one has suggested a cause yet; it proves nothing.","","Incorrect — bones naturally differ in size; balance is a prompt, not a rule.","Incorrect — deleting it removes the prompt and may hide causes, such as measurement problems."],bookRef:"Syllabus 2.1.1"},{id:"sv-2-479",phase:2,topic:"2.1.1",qtype:"statements",difficulty:1,stem:`Which statements about the structure of a fishbone diagram are CORRECT?

1. The effect being investigated is written at the head.
2. The major bones carry categories of potential causes.
3. Each cause is scored 9, 3 or 1 against weighted outputs.
4. A risk priority number is calculated for each cause.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:0,hint:"Separate the fishbone’s parts from the scoring done in the X-Y matrix and FMEA.",steps:[{title:"Key idea",body:"A fishbone has a head (the effect) and bones (categories and causes). It has no scoring."},{title:"Apply to the stem",body:"Statements 1 and 2 describe the diagram; 3 and 4 describe the X-Y matrix and FMEA."}],final:"Head and category bones only → answer **A**",whyWrong:["","Incorrect — statement 3 is false: scoring X’s 9/3/1 against weighted Y’s is the X-Y matrix.","Incorrect — statements 3 and 4 are both false; statement 3: scoring X’s 9/3/1 against weighted Y’s is the X-Y matrix.","Incorrect — statement 4 is false: RPNs are calculated in the FMEA, not on the fishbone."],bookRef:"Book p. 584 (glossary); Syllabus 2.1.1"},{id:"sv-2-480",phase:2,topic:"2.1.1",qtype:"statements",difficulty:2,stem:`Which two inputs from a mobile-network fishbone are normally classed as **noise**?

1. The antenna tilt angle set by the radio engineer.
2. Heavy rain that weakens the microwave link.
3. How each subscriber positions their phone indoors.
4. The standard checklist used for a site acceptance test.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:1,hint:"Noise = we cannot control it, are unaware of it, or it is too costly to control.",steps:[{title:"Key idea",body:"Weather and the behaviour of individuals are classic noise inputs."},{title:"Apply to the stem",body:"Tilt angle is controllable; the acceptance checklist is procedural."}],final:"Rain and user behaviour are noise → answer **B**",whyWrong:["Incorrect — statement 1 is false: tilt is a setting the engineer can adjust, so it is controllable.","","Incorrect — statement 4 is false: a standard checklist is a procedural input.","Incorrect — statements 1 and 4 are both false; statement 1: tilt is a setting the engineer can adjust, so it is controllable."],bookRef:"Book pp. 113–114; Syllabus 2.1.1"},{id:"sv-2-481",phase:2,topic:"2.1.1",qtype:"statements",difficulty:2,stem:`Which statements about **controllable** inputs are CORRECT?

1. They can be changed only by redesigning the product.
2. They are the inputs the team is unaware of.
3. Examples include speed, feed rate, temperature and pressure.
4. Breakthrough improvement comes mainly from these inputs.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:2,hint:"Book pp. 113 and 119 on controllable X’s.",steps:[{title:"Key idea",body:"Controllable inputs are adjusted while the process runs, such as speed or temperature."},{title:"Apply to the stem",body:"The book says breakthrough needs mainly controllable X’s, which go to the X-Y matrix."}],final:"Examples and breakthrough role → answer **C**",whyWrong:["Incorrect — statements 1 and 2 are both false; statement 1: controllable inputs are adjusted while the process runs, without redesign.","Incorrect — statement 2 is false: being unaware of an input is one reason it is classed as noise.","","Incorrect — statement 1 is false: controllable inputs are adjusted while the process runs, without redesign."],bookRef:"Book pp. 113, 119; Syllabus 2.1.1"},{id:"sv-2-482",phase:2,topic:"2.1.1",qtype:"statements",difficulty:3,stem:`Which statements about routing fishbone causes are CORRECT?

1. Controllable X’s are carried into the X-Y matrix.
2. Noise X’s are discarded because nothing can be done about them.
3. Procedural X’s are weighted from 1 to 10 in the X-Y matrix.
4. Noise X’s raise the risk of defects when entered in the FMEA.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:3,hint:"C → X-Y matrix; P and N → FMEA.",steps:[{title:"Key idea",body:"The book routes controllable X’s to the X-Y matrix and procedural and noise X’s to the FMEA."},{title:"Apply to the stem",body:"Noise raises risk and the RPN, which can justify investment."}],final:"C → X-Y; N raises FMEA risk → answer **D**",whyWrong:["Incorrect — statement 2 is false: noise X’s are kept and carried into the FMEA.","Incorrect — statements 2 and 3 are both false; statement 2: noise X’s are kept and carried into the FMEA.","Incorrect — statement 3 is false: procedural X’s are checked for compliance and carried into the FMEA.",""],bookRef:"Book p. 119; Syllabus 2.1.1"},{id:"sv-2-483",phase:2,topic:"2.1.1",qtype:"statements",difficulty:2,stem:`Which statements about drilling a fishbone branch with the **5 Whys** are CORRECT?

1. Each answer to “why?” can be added as a smaller bone.
2. Each link should be checked by asking “how do we know?”.
3. The answers are verified facts, so no data are needed later.
4. The drill should stop when it reaches a named individual.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:0,hint:"Whys deepen branches, but each link stays a hypothesis.",steps:[{title:"Key idea",body:"Each answer adds a sub-bone, and each link should be challenged with “how do we know?”."},{title:"Eliminate look-alikes",body:"Treating answers as proof, or stopping at a person, are classic errors."}],final:"Sub-bones and challenge each link → answer **A**",whyWrong:["","Incorrect — statement 3 is false: every answer is still a hypothesis to be tested with data.","Incorrect — statements 3 and 4 are both false; statement 3: every answer is still a hypothesis to be tested with data.","Incorrect — statement 4 is false: stopping at a person is the blame trap; ask why the system allowed it."],bookRef:"Syllabus 2.1.1"},{id:"sv-2-484",phase:2,topic:"2.1.1",qtype:"statements",difficulty:3,stem:`Which statements about the link between process mapping and the fishbone are CORRECT?

1. The fishbone must be completed before any process map is drawn.
2. A completed fishbone makes the process map unnecessary.
3. The process map steps help the team think of causes at each step.
4. Process mapping is itself one of the primary sources of X’s.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:2,hint:"Book pp. 98 and 118: map first, then fishbone.",steps:[{title:"Key idea",body:"The book’s exercise uses the high-level process map to build the fishbone."},{title:"Apply to the stem",body:"Process mapping, fishbone analysis and basic data analysis are the three sources of X’s."}],final:"Map feeds the fishbone; mapping is a source of X’s → answer **C**",whyWrong:["Incorrect — statements 1 and 2 are both false; statement 1: the book builds the fishbone from the high-level process map, so mapping comes first.","Incorrect — statement 2 is false: the map is still needed for the FMEA steps and VA/NVA analysis.","","Incorrect — statement 1 is false: the book builds the fishbone from the high-level process map, so mapping comes first."],bookRef:"Book pp. 98, 118; Syllabus 2.1.1"},{id:"sv-2-485",phase:2,topic:"2.1.1",qtype:"statements",difficulty:2,stem:`Which statements about building an FMEA from earlier Measure tools are CORRECT?

1. The potential causes of failure come from the fishbone.
2. The severity ratings are copied from the fishbone.
3. The detection ratings are copied from the fishbone.
4. The process steps come from the process map.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:3,hint:"Which earlier tool supplies which FMEA column?",steps:[{title:"Key idea",body:"FMEA steps come from the process map; potential causes (and their class) come from the fishbone."},{title:"Apply to the stem",body:"Severity, occurrence and detection are rated in the FMEA itself."}],final:"Causes from fishbone; steps from map → answer **D**",whyWrong:["Incorrect — statement 2 is false: the fishbone has no ratings; severity is scored by the team in the FMEA.","Incorrect — statements 2 and 3 are both false; statement 2: the fishbone has no ratings; severity is scored by the team in the FMEA.","Incorrect — statement 3 is false: detection ratings come from the current controls and MSA, not the fishbone.",""],bookRef:"Book pp. 127–131; Syllabus 2.1.1"},{id:"sv-2-486",phase:2,topic:"2.1.1",qtype:"statements",difficulty:2,stem:`Which statements about a fishbone session with mixed internal and vendor teams are CORRECT?

1. Only the vendor should propose causes, as it runs the process.
2. Causes should be written about the system, not about named individuals.
3. The output is a list of potential causes that need data to confirm.
4. The most-voted cause should be reported to the vendor as the root cause.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:1,hint:"Fishbone = shared, non-blaming picture of potential causes.",steps:[{title:"Key idea",body:"Writing causes about the system lets internal and vendor staff work on the same wall."},{title:"Apply to the stem",body:"The result is a list of hypotheses to be tested, not findings."}],final:"System-focused, hypotheses only → answer **B**",whyWrong:["Incorrect — statement 1 is false: a cross-functional team, including internal staff, gives a wider view of causes.","","Incorrect — statement 4 is false: votes are opinion; causes stay potential until data verify them.","Incorrect — statements 1 and 4 are both false; statement 1: a cross-functional team, including internal staff, gives a wider view of causes."],bookRef:"Syllabus 2.1.1"},{id:"sv-2-487",phase:2,topic:"2.1.1",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

A cause and effect diagram is a pictorial diagram in the shape of a fishbone showing all possible [?] that could affect a given process output.`,options:["controls","defects","specifications","variables"],answer:3,hint:"Recall the glossary definition on p. 584.",steps:[{title:"Key idea",body:"The glossary defines the fishbone as a diagram showing all possible **variables** that could affect a process output."},{title:"Apply to the stem",body:"Those variables are the potential X’s."}],final:"Glossary: “all possible variables” → answer **D**",whyWrong:["Incorrect — controls are how risks are detected or prevented, recorded in the FMEA and control plan.","Incorrect — the diagram shows causes that might create defects, not the defects themselves.","Incorrect — specifications are customer limits on the output, not the causes affecting it.",""],bookRef:"Book p. 584 (glossary); Syllabus 2.1.1"},{id:"sv-2-488",phase:2,topic:"2.1.1",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

Inputs that are affected by a standardised set of activities that bring a process step to completion are called [?] inputs.`,options:["controllable","critical","noise","procedural"],answer:3,hint:"C / P / N definitions, book p. 113.",steps:[{title:"Key idea",body:"The book defines procedural inputs as those affected by a standardised set of activities that complete a step."},{title:"Apply to the stem",body:"SOPs, checklists and fixed forms are typical examples."}],final:"Standardised activities = procedural → answer **D**",whyWrong:["Incorrect — controllable inputs are adjusted while the process runs, such as temperature or speed.","Incorrect — critical X’s are those proven by data to drive the Y.","Incorrect — noise inputs are those we cannot, or choose not to, control.",""],bookRef:"Book pp. 113–114; Syllabus 2.1.1"},{id:"sv-2-489",phase:2,topic:"2.1.1",qtype:"missing-word",difficulty:1,stem:`Identify the missing words in the following sentence.

Controllable X’s from the fishbone are carried into the [?] to find the vital few.`,options:["control plan","FMEA","Pareto chart","X-Y matrix"],answer:3,hint:"C → ? ; P and N → FMEA.",steps:[{title:"Key idea",body:"The book routes controllable X’s to the X-Y matrix (p. 119)."},{title:"Apply to the stem",body:"The X-Y matrix rates each X against the weighted Y’s to find the vital few."}],final:"Controllable X’s → X-Y matrix → answer **D**",whyWrong:["Incorrect — the control plan is built in Control to sustain verified solutions.","Incorrect — the FMEA mainly receives the procedural and noise X’s.","Incorrect — a Pareto chart ranks counted categories of real data, not fishbone X’s by weighted impact.",""],bookRef:"Book p. 119; Syllabus 2.1.1"},{id:"sv-2-490",phase:2,topic:"2.1.1",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

The horizontal arrow that leads to the head of a fishbone, and from which the category bones branch, is called the [?].`,options:["head","rib","spine","tail"],answer:2,hint:"Fishbone anatomy: head, spine, major bones, minor bones.",steps:[{title:"Key idea",body:"The spine is the main horizontal arrow pointing to the effect."},{title:"Apply to the stem",body:"Major (category) bones branch from the spine; minor bones carry causes."}],final:"Main arrow = spine → answer **C**",whyWrong:["Incorrect — the head holds the effect; the arrow leads into it.","Incorrect — “rib” is not a fishbone term; the branches are called bones.","","Incorrect — the tail is simply the start of the arrow and holds nothing."],bookRef:"Syllabus 2.1.1"},{id:"sv-2-491",phase:2,topic:"2.1.1",qtype:"missing-word",difficulty:2,stem:`Identify the missing words in the following sentence.

Asking “why?” repeatedly to drill from a first-pass cause down to an actionable underlying cause is called the [?].`,options:["5 Whys","5S","affinity method","Pareto principle"],answer:0,hint:"Depth technique used on each fishbone branch.",steps:[{title:"Key idea",body:"Repeating “why?” about five times pushes a symptom down to a cause the process can act on."},{title:"Apply to the stem",body:"Each answer becomes a smaller bone on the fishbone."}],final:"Repeated “why?” = 5 Whys → answer **A**",whyWrong:["","Incorrect — 5S is a Lean workplace-organisation method (Sort, Set in order, Shine, Standardise, Sustain).","Incorrect — the affinity method groups many ideas into themes; it does not drill down.","Incorrect — the Pareto principle says a few causes account for most of the effect."],bookRef:"Syllabus 2.1.1"},{id:"sv-2-492",phase:2,topic:"2.1.1",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

Noise inputs carried from the fishbone into the FMEA raise the risk of defects and therefore increase the [?].`,options:["Cpk","DPMO","RPN","RTY"],answer:2,hint:"What does the FMEA calculate for each failure mode?",steps:[{title:"Key idea",body:"The book says noise inputs raise the risk of defects under current methods, which shows as a higher risk priority number (RPN)."},{title:"Apply to the stem",body:"A high RPN shows where investment may be justified."}],final:"Noise raises the RPN → answer **C**",whyWrong:["Incorrect — Cpk is a capability index from a capability study, not an FMEA value.","Incorrect — DPMO counts defects per million opportunities from real data.","","Incorrect — rolled throughput yield is a process-map yield measure."],bookRef:"Book p. 119; Syllabus 2.1.1"},{id:"sv-2-493",phase:2,topic:"2.1.1",qtype:"not-except",difficulty:1,stem:"Which is NOT one of the **4Ps** used as fishbone categories for service processes?",options:["Plant","Policies","Procedures","Products"],answer:3,hint:"4Ps = Policies, Procedures, People, Plant.",steps:[{title:"Key idea",body:"The 4Ps are Policies, Procedures, People and Plant (or Place)."},{title:"Apply to the stem",body:"Products is not one of them."}],final:"Products is not a 4P → answer **D**",whyWrong:["Incorrect — Plant (buildings, equipment, systems) is one of the 4Ps.","Incorrect — Policies (rules from management) is one of the 4Ps.","Incorrect — Procedures (how work is done) is one of the 4Ps.",""],bookRef:"Syllabus 2.1.1"},{id:"sv-2-494",phase:2,topic:"2.1.1",qtype:"not-except",difficulty:3,stem:"Each of these is a reason for classifying a process input as **noise** EXCEPT:",options:["The team thinks it cannot be controlled","It is governed by a standard operating procedure","The team was not aware that it existed","It is too expensive or difficult to control"],answer:1,hint:"Noise = can’t control, unaware, or too costly/difficult.",steps:[{title:"Key idea",body:"The book lists three reasons an input is noise: we think we cannot control it, we are unaware of it, or it is too expensive or difficult to control."},{title:"Apply to the stem",body:"An input governed by an SOP is procedural, not noise."}],final:"SOP-governed = procedural, not noise → answer **B**",whyWrong:["Incorrect — this is a book reason for noise: we think we cannot control it.","","Incorrect — this is a book reason for noise: some inputs are noise because we do not know about them.","Incorrect — this is a book reason for noise: control would cost too much or be too hard."],bookRef:"Book pp. 113–114; Syllabus 2.1.1"},{id:"sv-2-495",phase:2,topic:"2.1.1",qtype:"not-except",difficulty:2,stem:"A fishbone diagram helps a team do each of the following EXCEPT:",options:["Prove which cause has the largest effect on the Y","Widen thinking beyond the cause people already suspect","Organise a large brainstorm into readable categories","Build a shared picture of the problem across functions"],answer:0,hint:"What can opinion-based tools never do?",steps:[{title:"Key idea",body:"A fishbone widens, organises and shares ideas."},{title:"Apply to the stem",body:"Proving size of effect requires data analysis in Analyze."}],final:"Fishbones do not prove effect size → answer **A**",whyWrong:["","Incorrect — widening thinking is a key benefit of the category bones.","Incorrect — organising ideas into categories is what the diagram does.","Incorrect — a shared wall picture is a recognised benefit of team fishbones."],bookRef:"Book pp. 228, 230; Syllabus 2.1.1"},{id:"sv-2-496",phase:2,topic:"2.1.1",qtype:"not-except",difficulty:2,stem:"All of the following are good facilitation rules for a fishbone session EXCEPT:",options:["Write ideas silently on notes before discussing them","Record the name of the person who caused each error","Write causes rather than solutions on the bones","Keep the agreed effect visible throughout the session"],answer:1,hint:"Facilitation rules: no criticism, causes not solutions, no names, head visible.",steps:[{title:"Key idea",body:"Naming individuals turns the session into blame and stops people speaking openly."},{title:"Apply to the stem",body:"Write the system cause instead, such as “handover gap on night shift”."}],final:"No names on the bones → answer **B**",whyWrong:["Incorrect — silent writing first is a good rule; it limits dominant voices.","","Incorrect — “causes, not solutions” is a good rule; solutions come in Improve.","Incorrect — keeping the head visible keeps the brainstorm focused."],bookRef:"Syllabus 2.1.1"},{id:"sv-2-497",phase:2,topic:"2.1.1",qtype:"not-except",difficulty:3,stem:"Which is NOT a normal output carried forward from a completed fishbone session?",options:["A verified root cause supported by a p-value","A list of candidate X’s for the X-Y matrix","A C, P or N class for each potential cause","Potential causes for the FMEA causes column"],answer:0,hint:"What has not happened yet when the fishbone is finished?",steps:[{title:"Key idea",body:"The fishbone produces tagged potential causes for the X-Y matrix and FMEA."},{title:"Apply to the stem",body:"Verification with p-values happens later, in Analyze."}],final:"No verified causes yet → answer **A**",whyWrong:["","Incorrect — controllable candidates are a normal output for the X-Y matrix.","Incorrect — the class is a normal output and travels into the FMEA Class column.","Incorrect — potential causes of failure in the FMEA come from the fishbone."],bookRef:"Book pp. 119, 131; Syllabus 2.1.1"},{id:"sv-2-498",phase:2,topic:"2.1.1",qtype:"not-except",difficulty:2,stem:"Each of these inputs on an injection-moulding fishbone is **controllable** EXCEPT:",options:["Injection pressure","Warehouse humidity","Barrel temperature","Cooling time"],answer:1,hint:"Book examples of controllable: speed, feed rate, temperature, pressure. Humidity is a noise example.",steps:[{title:"Key idea",body:"Pressure, temperature and time are machine settings."},{title:"Apply to the stem",body:"Warehouse humidity is an environmental input that the team does not control, so it is noise."}],final:"Humidity = noise → answer **B**",whyWrong:["Incorrect — pressure can be adjusted while the machine runs, so it is controllable.","","Incorrect — barrel temperature is a machine setting, so it is controllable.","Incorrect — cooling time is set on the machine, so it is controllable."],bookRef:"Book pp. 113–114; Syllabus 2.1.1"},{id:"sv-2-499",phase:2,topic:"2.1.1",qtype:"not-except",difficulty:2,stem:"A fishbone for *“Parcels delivered late”* is being built. Each of these causes belongs on the **Method** bone EXCEPT:",options:["Orders are released to drivers in one batch each morning","Routes are planned without traffic information","Delivery van breaks down on the route","The work instruction skips the address-check step"],answer:2,hint:"Method = procedures, rules and sequence of work. Machine = equipment and vehicles.",steps:[{title:"Key idea",body:"Method holds causes about how the work is organised and carried out."},{title:"Apply to the stem",body:"A vehicle breakdown is an equipment cause, so it belongs on Machine."}],final:"Van breakdown = Machine → answer **C**",whyWrong:["Incorrect — batch release is a way of working, so it belongs on Method.","Incorrect — how routes are planned is a procedure, so it belongs on Method.","","Incorrect — a work instruction is a procedure, so it belongs on Method."],bookRef:"Syllabus 2.1.1"},{id:"sv-2-500",phase:2,topic:"2.1.1",qtype:"not-except",difficulty:3,stem:"Each of these is a sign that a team’s fishbone needs more work EXCEPT:",options:["Every cause has been tagged C, P or N","The People bone is full of named individuals","The Measurement bone is empty and was never discussed","The head states a solution such as “hire more agents”"],answer:0,hint:"What does a finished, healthy fishbone look like?",steps:[{title:"Key idea",body:"A good fishbone is wide, deep and tagged."},{title:"Apply to the stem",body:"Full C/P/N tagging is a sign of a complete diagram, not a problem."}],final:"Full tagging is good practice → answer **A**",whyWrong:["","Incorrect — named people signal blame; causes should describe the system.","Incorrect — an undiscussed empty bone is a gap the facilitator should probe.","Incorrect — a solution at the head narrows the brainstorm; the head must be the effect."],bookRef:"Syllabus 2.1.1"},{id:"sv-2-501",phase:2,topic:"2.1.1",qtype:"scenario",difficulty:2,stem:"A fishbone for *“High signal loss on new fibre links”* includes the cause **“Longer cable runs increase loss.”** The team now has 40 paired readings of cable length (m) and loss (dB). Which tool should it use to check this cause?",options:["Affinity diagram","Another fishbone diagram","Pareto chart","Scatter diagram"],answer:3,hint:"Two continuous variables, one suspected X and one Y — which graph shows if they move together?",steps:[{title:"Key idea",body:"Fishbone causes are hypotheses that must be checked with data."},{title:"Apply to the stem",body:"Paired continuous data (length, loss) are plotted on a scatter diagram to see if loss rises with length."}],final:"Paired continuous X and Y → scatter diagram → answer **D**",whyWrong:["Incorrect — an affinity diagram groups ideas into themes; it cannot test a relationship in data.","Incorrect — a second fishbone would add more ideas, not check this one with data.","Incorrect — a Pareto chart ranks counts of categories; the data here are two continuous variables.",""],bookRef:"Book p. 118; Syllabus 2.1.1"},{id:"sv-2-502",phase:2,topic:"2.1.1",qtype:"scenario",difficulty:1,stem:"A Black Belt has typed the team’s causes into worksheet columns headed Man, Machine, Method, Material, Measurement and Environment. Which Minitab command draws the fishbone from these columns?",options:["Stat > Quality Tools > Pareto Chart","Stat > Quality Tools > Cause-and-Effect","Stat > Basic Statistics > Display Descriptive Statistics","Graph > Scatterplot"],answer:1,hint:"The fishbone is found among Minitab’s quality tools under its formal name.",steps:[{title:"Key idea",body:"Minitab calls the fishbone a cause-and-effect diagram."},{title:"Apply to the stem",body:"It is drawn with **Stat > Quality Tools > Cause-and-Effect**, using one column per category."}],final:"Minitab: Quality Tools > Cause-and-Effect → answer **B**",whyWrong:["Incorrect — this ranks counted categories; it does not draw a fishbone.","","Incorrect — this summarises numeric data such as means and standard deviations.","Incorrect — this plots two numeric variables against each other."],bookRef:"Syllabus 2.1.1"},{id:"sv-2-503",phase:2,topic:"2.1.1",qtype:"scenario",difficulty:3,stem:"On an MTTR fishbone, **“Travel time to remote cell sites”** was tagged noise. The team then proposes keeping spare parts at regional hubs close to those sites. What does this show about the input?",options:["A noise input must be deleted once a solution is proposed","The input was procedural from the start and was mis-tagged","A noise input can become controllable when the process is redesigned","Noise inputs are proven root causes and must be fixed first"],answer:2,hint:"Ask of every cause: is it, or should it be, controlled?",steps:[{title:"Key idea",body:"A tag reflects the current process. Under today’s design, travel time cannot be adjusted, so it is noise."},{title:"Apply to the stem",body:"Pre-positioning spares changes the design so the effect of distance can be managed — the input becomes controllable."}],final:"Redesign can turn noise into controllable → answer **C**",whyWrong:["Incorrect — inputs are not deleted; their class is updated as the process changes.","Incorrect — travel time is not governed by a procedure; it was noise under the old design.","","Incorrect — no fishbone input is proven; noise is about control, not proof."],bookRef:"Book pp. 113–114; Syllabus 2.1.1"},{id:"sv-2-504",phase:2,topic:"2.1.1",qtype:"scenario",difficulty:2,stem:"A bottling team’s fishbone for *“Fill volume below label claim”* lists **“Filler line speed”**, tagged C. The team wants to know how strongly this input affects fill volume, cost and spillage compared with other controllable inputs. Which tool should it use next?",options:["Control chart","FMEA","SIPOC","X-Y matrix"],answer:3,hint:"Controllable X’s, several Y’s, relative impact → which Measure tool?",steps:[{title:"Key idea",body:"Controllable X’s from the fishbone go into the X-Y matrix."},{title:"Apply to the stem",body:"The matrix rates each X against weighted Y’s (fill volume, cost, spillage) to find the vital few."}],final:"Controllable X vs several Y’s → X-Y matrix → answer **D**",whyWrong:["Incorrect — a control chart monitors stability over time; it does not compare inputs against several outputs.","Incorrect — the FMEA mainly receives procedural and noise inputs and rates failure risk.","Incorrect — SIPOC scopes suppliers, inputs, process, outputs and customers in Define.",""],bookRef:"Book p. 119; Syllabus 2.1.1"},{id:"sv-2-505",phase:2,topic:"2.1.1",qtype:"scenario",difficulty:3,stem:"A fishbone for *“Business-line faults escalated late”* includes **“Night shift does not follow the written escalation procedure.”** What should the team do FIRST with this procedural cause?",options:["Check compliance with the procedure and measure how often it is followed","Rate it 9, 3 or 1 against the Y’s in the X-Y matrix","Tag it as noise because people are unpredictable","Remove it, because procedures cannot cause late escalation"],answer:0,hint:"Book p. 119: procedures must be in total compliance.",steps:[{title:"Key idea",body:"All procedures must be in total compliance; this may need an effectiveness measure."},{title:"Apply to the stem",body:"Measuring and fixing compliance can remove defects and lets the team focus on controllable X’s."}],final:"Procedural cause → check compliance first → answer **A**",whyWrong:["","Incorrect — the X-Y matrix is mainly for controllable X’s; a procedure is first checked for compliance.","Incorrect — a defined procedure that is not followed is procedural, not noise.","Incorrect — non-compliance with procedures is a common cause of defects."],bookRef:"Book p. 119; Syllabus 2.1.1"},{id:"sv-2-506",phase:2,topic:"2.1.1",qtype:"scenario",difficulty:3,stem:"A fishbone for *“Banking app crashes after release”* lists **“Testers use whatever phone models are available in each test cycle.”** The team cannot standardise the phones in this project. How should this input be handled?",options:["Tag it as controllable and rank it in the X-Y matrix","Tag it as noise and carry it into the FMEA, where it raises the risk","Delete it, because the team cannot change it","Treat it as a verified root cause and report it to the sponsor"],answer:1,hint:"Inputs the team will not or cannot control → noise → FMEA.",steps:[{title:"Key idea",body:"An input that is impractical to control is classed as noise."},{title:"Apply to the stem",body:"Noise goes to the FMEA, where it increases risk and shows where investment may be justified."}],final:"Uncontrolled input → noise → FMEA → answer **B**",whyWrong:["Incorrect — the team has decided it cannot control the phones, so it is not controllable here.","","Incorrect — noise inputs are kept because they raise risk and may justify investment.","Incorrect — nothing on the fishbone is verified; it remains a potential cause."],bookRef:"Book p. 119; Syllabus 2.1.1"},{id:"sv-2-507",phase:2,topic:"2.1.1",qtype:"scenario",difficulty:3,stem:"A managed-services contract shows repeated SLA breaches. The Black Belt wants to explore causes with the vendor without the session turning into a dispute about blame. Which approach is MOST appropriate?",options:["Issue a formal finding listing the vendor engineers involved","Draw a Pareto chart of breaches by engineer name","Run a joint fishbone workshop that describes causes in the system, not individuals","Build a control chart and wait for special causes"],answer:2,hint:"The fishbone describes the system, so internal and vendor staff can work on the same wall.",steps:[{title:"Key idea",body:"A fishbone is a fair, non-confrontational way to explore causes because it focuses on the system."},{title:"Apply to the stem",body:"Vendor and internal staff can contribute together; the output is a set of hypotheses to verify."}],final:"Joint, system-focused fishbone → answer **C**",whyWrong:["Incorrect — naming individuals invites blame and gives no structured view of possible causes.","Incorrect — ranking by person focuses on blame and assumes people are the cause.","","Incorrect — a control chart shows stability; it does not explore possible causes with the team."],bookRef:"Syllabus 2.1.1"},{id:"sv-2-508",phase:2,topic:"2.1.1",qtype:"scenario",difficulty:3,stem:"A team drilling the Material bone writes: *“P1 faults wait for spare cards”* → *“Depot is out of stock.”* It stops there and proposes buying more spares. What is the BEST assessment?",options:["The team stopped at a symptom and jumped to a solution; it should keep asking why and verify the cause","The team followed the method correctly, as it found a fixable cause","The team should have tagged the cause as noise and stopped","The team should move the cause to the head of the diagram"],answer:0,hint:"Why is the depot out of stock? Keep asking until the cause is actionable, then verify.",steps:[{title:"Key idea",body:"The first answers are usually symptoms one level down."},{title:"Apply to the stem",body:"Asking why again may reveal stale reorder points or no owner for spares planning."},{title:"Eliminate look-alikes",body:"Proposing a purchase skips both deeper drilling and verification with data."}],final:"Symptom + solution jump → keep drilling → answer **A**",whyWrong:["","Incorrect — two levels rarely reach an underlying cause, and buying spares is a solution, not a verified cause.","Incorrect — stock levels can be adjusted, and tagging does not replace drilling deeper.","Incorrect — the head holds the effect; a cause is never moved there."],bookRef:"Syllabus 2.1.1"},{id:"sv-2-509",phase:2,topic:"2.1.1",qtype:"scenario",difficulty:2,stem:"During a fishbone session an engineer writes **“Omar forgot to back up the config before the change.”** What should the facilitator do?",options:["Keep it as written, because naming people makes causes clear","Rewrite it as a system cause, such as “no backup step in the change checklist”","Move it to the head as the effect of the diagram","Delete it, because human error cannot be improved"],answer:1,hint:"No names: ask why the system allowed the error.",steps:[{title:"Key idea",body:"Facilitation rule: no names on the bones."},{title:"Apply to the stem",body:"The underlying cause is that the process does not force a backup, so write that."}],final:"Replace names with the system cause → answer **B**",whyWrong:["Incorrect — names lead to blame and silence; causes should describe the system.","","Incorrect — the head holds the agreed effect, not an individual cause.","Incorrect — human error usually points to a system gap that can be fixed."],bookRef:"Syllabus 2.1.1"},{id:"sv-2-510",phase:2,topic:"2.1.1",qtype:"scenario",difficulty:2,stem:"A paint shop writes the head of its fishbone as *“Paint defects caused by humid weather.”* What is the main problem with this head?",options:["It is too specific, because heads should be general themes","It should name the solution so that the team stays focused","It contains a suspected cause, which narrows the brainstorm before it begins","Weather cannot appear anywhere on a fishbone diagram"],answer:2,hint:"The head holds the effect only — no cause, no solution.",steps:[{title:"Key idea",body:"An embedded cause (“caused by humid weather”) tells the team the answer before it starts."},{title:"Apply to the stem",body:"A better head states the measurable effect, for example the defect rate against target; humidity goes on the Environment bone."}],final:"A cause in the head narrows the brainstorm → answer **C**",whyWrong:["Incorrect — heads should be specific and measurable; this one is flawed because it contains a cause.","Incorrect — solutions never belong at the head; they come in Improve.","","Incorrect — weather is a valid cause on the Mother Nature (Environment) bone."],bookRef:"Syllabus 2.1.1"},{id:"sv-2-511",phase:2,topic:"2.1.1",qtype:"scenario",difficulty:2,stem:"A Black Belt is preparing a fishbone workshop on *“Number-porting requests rejected.”* With whom should the Black Belt agree the wording of the head BEFORE the session?",options:["The finance controller","The newest team member","The process owner","The software vendor"],answer:2,hint:"Preparation step 1: agree the problem statement wording with the person accountable for the process.",steps:[{title:"Key idea",body:"The head is the agreed effect from the problem statement."},{title:"Apply to the stem",body:"The Black Belt agrees its wording with the process owner before the session, so the team brainstorms the right problem."}],final:"Agree the head with the process owner → answer **C**",whyWrong:["Incorrect — finance validates savings; it does not own the problem wording.","Incorrect — new members contribute ideas, but the problem wording is agreed with the owner of the process.","","Incorrect — the vendor may join the session, but it does not own the process problem statement."],bookRef:"Syllabus 2.1.1"},{id:"sv-2-512",phase:2,topic:"2.1.1",qtype:"scenario",difficulty:3,stem:"In Analyze, the team tests the fishbone cause **“Cable from supplier A causes more joint failures than cable from supplier B.”** A two-sample test gives p = 0.41 with α = 0.05. What should happen to this cause on the fishbone?",options:["It is confirmed as the root cause because the test was run","It is moved to the head of the diagram as the new effect","It is re-tagged as procedural because it involves suppliers","It is not supported by the data, so it is marked as disproven and the diagram is updated"],answer:3,hint:"p > α → fail to reject H₀. The fishbone is a living document.",steps:[{title:"Key idea",body:"Fishbone causes are hypotheses tested in Analyze."},{title:"Apply to the stem",body:"p = 0.41 is greater than 0.05, so the team fails to reject H₀: no evidence that supplier matters."},{title:"Eliminate look-alikes",body:"The diagram is updated (the branch is struck through) and attention moves to other causes."}],final:"p > α → cause not supported → update diagram → answer **D**",whyWrong:["Incorrect — p > α means the team fails to reject H₀; the data do not support the cause.","Incorrect — the head always holds the effect; a tested cause stays on its bone.","Incorrect — the test result does not change whether the input is controllable, procedural or noise.",""],bookRef:"Book pp. 228, 230; Syllabus 2.1.1"},{id:"sv-2-513",phase:2,topic:"2.1.1",qtype:"best-action",difficulty:2,stem:"To save the team’s time, a Black Belt drew the fishbone for *“Late fibre installations”* alone at her desk overnight and presented it as finished the next morning. Was this an appropriate action, and why?",options:["Yes, because the Black Belt knows the fishbone method best","Yes, because a fishbone needs no input once the problem is defined","No, because the diagram should be checked with a data sample first","No, because a fishbone should capture the knowledge of the people who do the work"],answer:3,hint:"The book’s exercise: build the fishbone with your project team if possible.",steps:[{title:"Key idea",body:"A fishbone is a team tool that pools the knowledge of people who do and receive the work."},{title:"Apply to the stem",body:"Drawing it alone misses causes and loses buy-in, so the action was not appropriate."}],final:"Team knowledge is the point of the tool → answer **D**",whyWrong:["Incorrect — method knowledge does not replace the process knowledge of the people doing the work.","Incorrect — the causes come from the team’s brainstorming; defining the problem is only the start.","Incorrect — the fishbone does not need data first; the problem is that the team was left out.",""],bookRef:"Book p. 98; Syllabus 2.1.1"},{id:"sv-2-514",phase:2,topic:"2.1.1",qtype:"best-action",difficulty:3,stem:"On a fishbone for *“Fibre joints fail the loss test”*, technicians often skip the cleaning step written in the SOP. The Black Belt tagged this cause **noise**, because “people are unpredictable”. Was this an appropriate action, and why?",options:["Yes, because behaviour of individuals is always classed as noise","Yes, because noise inputs receive the most attention in the FMEA","No, because a defined procedure that is not followed is procedural, so compliance is checked first","No, because the cause should have been tagged controllable and sent to the X-Y matrix"],answer:2,hint:"A defined procedure exists → which class? What does the book require of procedures?",steps:[{title:"Key idea",body:"Procedural inputs are governed by a standardised set of activities; the book requires total compliance."},{title:"Apply to the stem",body:"Calling non-compliance “noise” discards a fixable cause and blames individuals."}],final:"Skipped SOP = procedural, not noise → answer **C**",whyWrong:["Incorrect — individual variation outside any procedure can be noise, but a skipped SOP step is a procedural issue.","Incorrect — the tag must describe the input correctly; it is not chosen to attract attention.","","Incorrect — the step is governed by an SOP, so it is procedural, not a controllable setting."],bookRef:"Book p. 119; Syllabus 2.1.1"},{id:"sv-2-515",phase:2,topic:"2.1.1",qtype:"best-action",difficulty:2,stem:"A fishbone for *“Cable-duct repairs overrun”* includes **“Monsoon flooding of ducts”**, tagged noise. The Black Belt kept it on the diagram and carried it into the FMEA. Was this an appropriate action, and why?",options:["Yes, because flooding is a proven root cause of the overruns","Yes, because noise inputs raise risk in the FMEA and can justify investment","No, because inputs that cannot be controlled should be deleted","No, because noise inputs belong in the X-Y matrix"],answer:1,hint:"Where do noise inputs go, and why?",steps:[{title:"Key idea",body:"Noise inputs go to the FMEA, where they raise the risk (RPN) under current methods."},{title:"Apply to the stem",body:"Keeping flooding visible shows where investment or robust design may be justified."}],final:"Noise → FMEA is correct → answer **B**",whyWrong:["Incorrect — nothing on a fishbone is proven; the action is right for a different reason.","","Incorrect — deleting noise hides risk; the book carries noise into the FMEA.","Incorrect — the X-Y matrix mainly receives controllable inputs."],bookRef:"Book p. 119; Syllabus 2.1.1"},{id:"sv-2-516",phase:2,topic:"2.1.1",qtype:"best-action",difficulty:2,stem:"During a fishbone session, a senior manager criticised each idea as it was offered and contributions dried up. The facilitator restated the no-criticism rule and switched to silent writing on sticky notes. Was this an appropriate action, and why?",options:["Yes, because idea generation needs no judgement, and silent writing limits dominant voices","Yes, because the manager’s ideas could then be voted as the root cause","No, because criticism during brainstorming removes weak causes early","No, because the facilitator should have ended the session and drawn the diagram alone"],answer:0,hint:"Facilitation rules: no criticism during generation; silent writing first.",steps:[{title:"Key idea",body:"Ideas are not judged while they are being generated."},{title:"Apply to the stem",body:"Silent writing collects every person’s ideas before senior voices can steer the list."}],final:"Protect idea generation → answer **A**",whyWrong:["","Incorrect — no root cause is chosen at this stage; voting on the manager’s ideas defeats the purpose.","Incorrect — judging ideas during generation stops people contributing; evaluation comes later with data.","Incorrect — a diagram drawn alone loses the team’s knowledge."],bookRef:"Syllabus 2.1.1"},{id:"sv-2-517",phase:2,topic:"2.1.1",qtype:"best-action",difficulty:3,stem:"A Black Belt copied all 45 causes from the fishbone straight into the rows of the X-Y matrix without tagging them controllable, procedural or noise. Was this an appropriate action, and why?",options:["Yes, because the X-Y matrix is designed to accept every type of input","Yes, because tagging inputs is done only in Analyze","No, because the causes must first be verified with hypothesis tests","No, because only controllable X’s go to the X-Y matrix; procedural and noise X’s go to the FMEA"],answer:3,hint:"Tag first, then route: C → X-Y; P and N → FMEA.",steps:[{title:"Key idea",body:"The C/P/N tag decides which tool each cause goes to."},{title:"Apply to the stem",body:"Skipping the tags overloads the X-Y matrix with procedures and noise that belong in the FMEA."}],final:"Tag before routing → answer **D**",whyWrong:["Incorrect — the book routes mainly controllable X’s to the X-Y matrix.","Incorrect — C/P/N tagging is done on the fishbone in Measure.","Incorrect — verification comes later in Analyze; the X-Y matrix is itself a prioritisation of unverified X’s.",""],bookRef:"Book p. 119; Syllabus 2.1.1"},{id:"sv-2-518",phase:2,topic:"2.1.1",qtype:"best-action",difficulty:3,stem:"After the fishbone workshop, the Black Belt’s steering-committee slide is titled *“Root causes of late installs”* and lists the five most-voted causes. Was this an appropriate action, and why?",options:["Yes, because the team’s vote is enough to confirm a root cause","Yes, because Measure is the phase in which root causes are confirmed","No, because fishbone causes are potential causes until data in Analyze verify them","No, because the slide should list all causes in alphabetical order"],answer:2,hint:"Measure identifies X’s; Analyze proves them.",steps:[{title:"Key idea",body:"At the end of Measure, fishbone causes are hypotheses."},{title:"Apply to the stem",body:"Labelling them “root causes” overstates the evidence; “potential causes” is correct."}],final:"Potential, not root, causes → answer **C**",whyWrong:["Incorrect — votes record opinion; the book calls team tools organised brainstorming, not data.","Incorrect — Measure identifies X’s; Analyze proves or disproves them.","","Incorrect — ordering is not the problem; calling unverified causes “root causes” is."],bookRef:"Book pp. 228, 230; Syllabus 2.1.1"},{id:"sv-2-519",phase:2,topic:"2.1.1",qtype:"best-action",difficulty:2,stem:"A technician’s sticky note on the Machine bone reads **“Buy a new fusion splicer.”** What is the BEST action for the facilitator?",options:["Ask what problem the note implies and record that cause, such as “splicer produces high-loss joints”","Accept the note, because solutions speed up the project","Move the note to the head of the diagram","Remove the note and ask the technician to stay silent"],answer:0,hint:"Facilitation rule: causes, not solutions.",steps:[{title:"Key idea",body:"A solution on a sticky note usually hides a suspected cause."},{title:"Apply to the stem",body:"Turn it into the cause it implies and keep the solution for Improve."}],final:"Convert the solution into its cause → answer **A**",whyWrong:["","Incorrect — solutions on a fishbone skip analysis; they belong in Improve after causes are verified.","Incorrect — the head holds the agreed effect, not a proposed purchase.","Incorrect — the idea hides a useful cause; discouraging the technician loses knowledge."],bookRef:"Syllabus 2.1.1"},{id:"sv-2-520",phase:2,topic:"2.1.1",qtype:"output",difficulty:2,stem:`A team exports its tagged fishbone causes for *“Mobile data sessions drop”*:

\`\`\`
Cause                                Bone         Tag
Handover parameter set too tight     Machine      C
Site audit checklist not followed    Method       P
Heavy rain on microwave links        Environment  C
Antenna tilt set incorrectly         Machine      C
\`\`\`

Which cause has the **wrong tag**?`,options:["Handover parameter set too tight","Heavy rain on microwave links","Site audit checklist not followed","Antenna tilt set incorrectly"],answer:1,hint:"Weather is a classic example of one class.",steps:[{title:"Key idea",body:"Controllable = adjustable while running; procedural = governed by an SOP; noise = cannot or will not be controlled."},{title:"Apply to the stem",body:"Rain cannot be controlled, so it should be tagged N, not C."}],final:"Rain should be noise → answer **B**",whyWrong:["Incorrect — a network parameter can be adjusted while the network runs, so C is right.","","Incorrect — a checklist is a standard procedure, so P is right.","Incorrect — tilt is an adjustable setting, so C is right."],bookRef:"Book pp. 113–114; Syllabus 2.1.1"},{id:"sv-2-521",phase:2,topic:"2.1.1",qtype:"output",difficulty:1,stem:`A team records the drilling of one fishbone branch:

\`\`\`
Effect: P2 restore time > 4 h SLA
Material
  Faults wait for replacement line cards
    Depot frequently out of stock
      Reorder points use 3-year-old failure rates
        No role owns spares planning
Method
  Field team dispatched before remote checks
\`\`\`

Which entry is the **deepest** cause found so far on the Material branch?`,options:["No role owns spares planning","Faults wait for replacement line cards","Depot frequently out of stock","Field team dispatched before remote checks"],answer:0,hint:"Each indent is one more “why?”.",steps:[{title:"Key idea",body:"Each indented line is the answer to “why?” about the line above it."},{title:"Apply to the stem",body:"The most indented Material entry is “No role owns spares planning”."}],final:"Most indented Material entry → answer **A**",whyWrong:["","Incorrect — this is the first-level cause on the Material bone, the shallowest entry.","Incorrect — this is a second-level cause; the team asked why again below it.","Incorrect — this cause is on the Method branch, not the Material branch."],bookRef:"Syllabus 2.1.1"},{id:"sv-2-522",phase:2,topic:"2.1.1",qtype:"output",difficulty:2,stem:`A team’s tagged cause list for *“Prepaid top-ups fail”* reads:

\`\`\`
Cause                                    Tag
Payment-gateway timeout setting          C
Top-up retry limit in the system         C
Agents follow the refund SOP             P
Customer bank outages                    N
\`\`\`

Which causes should go into the **X-Y matrix**?`,options:["Refund SOP and customer bank outages","Payment-gateway timeout setting and top-up retry limit","Customer bank outages only","All four causes, in the order listed"],answer:1,hint:"C → X-Y matrix; P and N → FMEA.",steps:[{title:"Key idea",body:"The X-Y matrix receives the controllable X’s."},{title:"Apply to the stem",body:"The two C-tagged causes are the timeout setting and the retry limit."}],final:"The two C causes → answer **B**",whyWrong:["Incorrect — these are procedural and noise causes, which go to the FMEA.","","Incorrect — noise causes go to the FMEA, where they raise risk.","Incorrect — only the controllable causes are carried into the X-Y matrix."],bookRef:"Book p. 119; Syllabus 2.1.1"},{id:"sv-2-523",phase:2,topic:"2.1.1",qtype:"output",difficulty:3,stem:`After the fishbone session, the team collects data on 200 breached tickets:

\`\`\`
Cause (from fishbone)         Team votes   Share of breaches in data
Technician skills                 9               8%
Spares not at depot               4              46%
Wrong fault category logged       3              31%
Access to customer premises       2              15%
\`\`\`

Which conclusion is BEST supported?`,options:["Technician skills is the root cause because it received the most votes","The data should be ignored because the team knows the process best","The most-voted cause is not the biggest contributor, so team opinion must be checked with data","Every cause matters equally, so all four need the same attention"],answer:2,hint:"Fishbone votes = organised brainstorming, not data.",steps:[{title:"Key idea",body:"The team voted technician skills highest (9 votes)."},{title:"Apply to the stem",body:"The data link spares to 46% of breaches and skills to only 8%."},{title:"Eliminate look-alikes",body:"Data later may show that a cause the team felt sure about is not important (book p. 118)."}],final:"Votes and data disagree → trust data → answer **C**",whyWrong:["Incorrect — votes are opinion; the data show skills linked to only 8% of breaches.","Incorrect — the book warns that team tools are not real data; data take priority.","","Incorrect — the shares differ widely; spares and wrong categorisation stand out."],bookRef:"Book p. 118; Syllabus 2.1.1"},{id:"sv-2-524",phase:2,topic:"2.1.1",qtype:"output",difficulty:2,stem:`A Black Belt reviews a team’s 5 Whys log for one fishbone branch:

\`\`\`
Effect: Router configuration lost after change
Why 1: Change applied without a config backup
Why 2: Engineer did not take a backup
Why 3: Engineer Salim was careless
(stopped)
\`\`\`

Which conclusion about this log is CORRECT?`,options:["It is complete because it reached a specific person","It is invalid because it has fewer than five whys","It proves the root cause, so the change process needs no review","It stops at blaming a person; the team should ask why the process allowed a change without a backup"],answer:3,hint:"Ask why the system allowed the mistake.",steps:[{title:"Key idea",body:"A person is rarely the root cause."},{title:"Apply to the stem",body:"The next why might be “the change checklist has no backup step”, which the process can fix."}],final:"Blame stop — keep drilling → answer **D**",whyWrong:["Incorrect — reaching a person is the blame trap, not a root cause.","Incorrect — five is a guideline; the problem is where it stopped, not how many whys.","Incorrect — the log is a hypothesis, and it points to a process gap that needs review.",""],bookRef:"Syllabus 2.1.1"},{id:"sv-2-525",phase:2,topic:"2.1.1",qtype:"output",difficulty:3,stem:`A team summarises three fishbone inputs for *“Order activation delays”*:

\`\`\`
Input                        Adjustable while    Governed by a     Practical to
                             process runs?       standard routine? control?
Provisioning batch interval  Yes                 No                Yes
Order validation checklist   No                  Yes               Yes
Customer’s own router model  No                  No                No
\`\`\`

Which input is **procedural**?`,options:["Order validation checklist","Provisioning batch interval","Customer’s own router model","Both the batch interval and the checklist"],answer:0,hint:"Procedural = governed by a standardised set of activities.",steps:[{title:"Key idea",body:"C = adjustable while running; P = standard routine; N = not practical to control."},{title:"Apply to the stem",body:"Only the validation checklist is governed by a standard routine."}],final:"Standard routine → procedural → answer **A**",whyWrong:["","Incorrect — it is adjustable while the process runs, so it is controllable.","Incorrect — it is neither adjustable nor practical to control, so it is noise.","Incorrect — the batch interval is adjustable while the process runs, so it is controllable, not procedural."],bookRef:"Book pp. 113–114; Syllabus 2.1.1"},{id:"sv-2-526",phase:2,topic:"2.1.1",qtype:"output",difficulty:2,stem:`A Black Belt’s Measure-phase tracker shows:

\`\`\`
Measure step                          Status
Detailed process map                  Done
Fishbone (identify all process X’s)   Done
X-Y matrix / FMEA                     Not started
Measurement system analysis           Not started
Stability and capability              Not started
\`\`\`

What is the NEXT step?`,options:["Run a capability study on the Y","Use the X-Y matrix and FMEA to select the vital few X’s","Start a designed experiment on every fishbone cause","Draw a second fishbone to confirm the first one"],answer:1,hint:"Roadmap: map → fishbone → X-Y/FMEA → MSA → stability → capability.",steps:[{title:"Key idea",body:"The book’s Measure roadmap moves from identifying all X’s to selecting the vital few."},{title:"Apply to the stem",body:"The fishbone is done, so the X-Y matrix and FMEA come next."}],final:"Next: X-Y matrix and FMEA → answer **B**",whyWrong:["Incorrect — capability comes after the X’s are prioritised and the measurement system is checked.","","Incorrect — DOE is an Improve tool and needs a short list of verified X’s.","Incorrect — another fishbone adds opinion; the roadmap moves on to prioritisation."],bookRef:"Book pp. 228, 230; Syllabus 2.1.1"},{id:"sv-2-527",phase:2,topic:"2.1.1",qtype:"true-false",difficulty:1,stem:"A fishbone diagram ranks potential causes from the most important to the least important.",options:["True","False"],answer:1,hint:"Does the fishbone produce any scores or counts?",steps:[{title:"Key idea",body:"A fishbone is a categorised list of potential causes with no scoring."},{title:"Apply to the stem",body:"Ranking happens later with data (Pareto) or team ratings (X-Y matrix)."}],final:"No ranking on a fishbone → answer **False**",whyWrong:["Incorrect — the fishbone only lists and groups causes; ranking needs a Pareto chart or an X-Y matrix.",""],bookRef:"Syllabus 2.1.1"},{id:"sv-2-528",phase:2,topic:"2.1.1",qtype:"true-false",difficulty:2,stem:"The major bones of a fishbone may be the main steps of the process map instead of the 6M categories.",options:["True","False"],answer:0,hint:"Are the 6Ms compulsory?",steps:[{title:"Key idea",body:"A process fishbone uses the major steps of the process map as its bones."},{title:"Apply to the stem",body:"This works well once the Level 1 map exists, so the statement is true."}],final:"Process steps can be the bones → answer **True**",whyWrong:["","Incorrect — categories are prompts, and a process fishbone uses the process steps as its bones."],bookRef:"Syllabus 2.1.1"},{id:"sv-2-529",phase:2,topic:"2.1.1",qtype:"true-false",difficulty:1,stem:"The 4Ps category set for service fishbones includes an explicit Measurement bone.",options:["True","False"],answer:1,hint:"4Ps = Policies, Procedures, People, Plant.",steps:[{title:"Key idea",body:"The 4Ps do not include Measurement."},{title:"Apply to the stem",body:"If data quality is suspect, a team using the 4Ps may add a Measurement bone."}],final:"No Measurement bone in the 4Ps → answer **False**",whyWrong:["Incorrect — the 4Ps are Policies, Procedures, People and Plant; Measurement is not one of them.",""],bookRef:"Syllabus 2.1.1"},{id:"sv-2-530",phase:2,topic:"2.1.1",qtype:"true-false",difficulty:2,stem:"When a fishbone branch is drilled with the 5 Whys, one “why?” can have several answers, and each answer becomes its own sub-bone.",options:["True","False"],answer:0,hint:"Branch, don’t chain blindly.",steps:[{title:"Key idea",body:"Most “whys” have more than one answer."},{title:"Apply to the stem",body:"Each answer is added as a separate smaller bone, so the statement is true."}],final:"Whys can branch → answer **True**",whyWrong:["","Incorrect — branching is expected; most “whys” have more than one answer."],bookRef:"Syllabus 2.1.1"},{id:"sv-2-531",phase:2,topic:"2.1.1",qtype:"true-false",difficulty:1,stem:"The Class column (C, P or N) of the FMEA is filled from the classification made on the fishbone.",options:["True","False"],answer:0,hint:"Book p. 131: which FMEA columns come from the fishbone?",steps:[{title:"Key idea",body:"The FMEA’s potential causes of failure and their class come from the fishbone."},{title:"Apply to the stem",body:"So the statement is true."}],final:"Class column comes from the fishbone → answer **True**",whyWrong:["","Incorrect — the book states that the FMEA class and potential causes come from the fishbone."],bookRef:"Book p. 131; Syllabus 2.1.1"},{id:"sv-2-532",phase:2,topic:"2.1.1",qtype:"sequence",difficulty:2,stem:`A team drills one branch of a fishbone for *“Wrong parts picked”*. Put the answers in order from the **first-level cause** to the **deepest cause**:

- **P** Bin labels show old part numbers
- **Q** Nobody owns label updates after engineering changes
- **R** Pickers take parts from the wrong bin
- **S** Engineering changes are not sent to the warehouse`,options:["P, R, Q, S","R, S, P, Q","Q, S, P, R","R, P, S, Q"],answer:3,hint:"Each step answers “why?” about the one before.",steps:[{title:"Key idea",body:"Start at the cause nearest the effect and ask why each time."},{title:"Apply to the stem",body:"Wrong bin (R) → why? old labels (P) → why? changes not sent (S) → why? no owner (Q)."}],final:"R → P → S → Q → answer **D**",whyWrong:["Incorrect — the first-level cause is the picking error (R); labels (P) explain why it happens.","Incorrect — changes not being sent (S) explains the old labels (P), so P must come before S.","Incorrect — this is the reverse order, from deepest cause back to the first-level cause.",""],bookRef:"Syllabus 2.1.1"},{id:"sv-2-533",phase:2,topic:"2.1.1",qtype:"sequence",difficulty:2,stem:`Put these Measure-phase activities in the order shown on the book’s roadmap:

- **P** Select the vital few X’s (X-Y matrix, FMEA)
- **Q** Detailed process mapping
- **R** Assess the measurement system
- **S** Identify all process X’s (fishbone)`,options:["S, Q, P, R","Q, P, S, R","Q, S, P, R","Q, S, R, P"],answer:2,hint:"Map → find all X’s → prioritise → measurement system → stability → capability.",steps:[{title:"Key idea",body:"The roadmap moves from mapping to finding X’s, then to prioritising them."},{title:"Apply to the stem",body:"Order: process map (Q) → fishbone (S) → X-Y/FMEA (P) → MSA (R)."}],final:"Q → S → P → R → answer **C**",whyWrong:["Incorrect — the book builds the fishbone from the process map, so mapping comes first.","Incorrect — the vital few cannot be selected before all X’s are identified.","","Incorrect — on the roadmap, selecting the vital few comes before the measurement system step."],bookRef:"Book pp. 228, 230; Syllabus 2.1.1"},{id:"sv-2-534",phase:2,topic:"2.1.1",qtype:"sequence",difficulty:2,stem:`Put the journey of one **controllable** cause in order:

- **P** Rate it against the weighted Y’s in the X-Y matrix
- **Q** Write it on the fishbone during brainstorming
- **R** Test its effect on the Y with data in Analyze
- **S** Tag it C on the fishbone`,options:["S, Q, P, R","Q, S, P, R","Q, P, S, R","Q, S, R, P"],answer:1,hint:"Brainstorm → tag → prioritise → verify.",steps:[{title:"Key idea",body:"A cause is generated, classified, prioritised and then verified."},{title:"Apply to the stem",body:"Order: write (Q) → tag C (S) → X-Y matrix (P) → Analyze (R)."}],final:"Q → S → P → R → answer **B**",whyWrong:["Incorrect — a cause must be written on the diagram before it can be tagged.","","Incorrect — the tag decides routing, so tagging comes before the X-Y matrix.","Incorrect — the X-Y matrix prioritises X’s in Measure, before they are tested in Analyze."],bookRef:"Book p. 119; Syllabus 2.1.1"},{id:"sv-2-535",phase:2,topic:"2.1.1",qtype:"sequence",difficulty:3,stem:`During the brainstorming part of a fishbone workshop, put these facilitation steps in order:

- **P** Drill each branch by asking “why?” and add sub-bones
- **Q** Participants read their notes aloud and place them on the bones
- **R** Check the balance of the bones and probe empty ones
- **S** Each person writes causes silently, one per note`,options:["Q, S, P, R","S, P, Q, R","S, Q, P, R","S, Q, R, P"],answer:2,hint:"Write → place → deepen → review.",steps:[{title:"Key idea",body:"Silent writing comes first, then placing, then drilling, then a balance check."},{title:"Apply to the stem",body:"Order: S → Q → P → R."}],final:"S → Q → P → R → answer **C**",whyWrong:["Incorrect — notes must be written (S) before they can be read aloud and placed (Q).","Incorrect — branches are drilled after the notes have been placed on the bones.","","Incorrect — balance is checked after drilling, so new sub-bones are included."],bookRef:"Syllabus 2.1.1"},{id:"sv-2-536",phase:2,topic:"2.1.1",qtype:"sequence",difficulty:2,stem:`Put these DMAIC activities for one problem in order:

- **P** Implement and pilot a solution for the verified cause
- **Q** Build a fishbone of potential causes
- **R** Write a measurable problem statement
- **S** Verify the suspected causes with data`,options:["Q, R, S, P","R, S, Q, P","R, Q, P, S","R, Q, S, P"],answer:3,hint:"Define → Measure → Analyze → Improve.",steps:[{title:"Key idea",body:"Define writes the problem statement; Measure builds the fishbone; Analyze verifies; Improve solves."},{title:"Apply to the stem",body:"Order: R → Q → S → P."}],final:"R → Q → S → P → answer **D**",whyWrong:["Incorrect — the fishbone head is taken from the problem statement, so the statement comes first.","Incorrect — causes must be listed on the fishbone before they can be verified.","Incorrect — solutions are implemented only after causes are verified.",""],bookRef:"Book pp. 228, 230; Syllabus 2.1.1"},{id:"sv-2-537",phase:2,topic:"2.1.2",qtype:"concept",difficulty:2,stem:"Which statement describes information that a process map gives the team for later Measure work?",options:["It shows the points where data such as cycle times, defects and inventory can be collected","It proves which process inputs cause the defects","It sets the customer’s specification limits for each output","It calculates the sigma level of the process"],answer:0,hint:"Book p. 100: what does mapping give you for later tools?",steps:[{title:"Key idea",body:"The book lists what mapping provides: X’s, Y’s, VA/NVA steps, data collection points, decision points, quick fixes and control needs."},{title:"Apply to the stem",body:"Data collection points (cycle times, defects, inventory, cost of poor quality) are one of these."}],final:"Map shows data collection points → answer **A**",whyWrong:["","Incorrect — a map suggests inputs (X’s); proving their effect needs data analysis in Analyze.","Incorrect — specification limits come from customer requirements, not from drawing the map.","Incorrect — the sigma level comes from defect or capability data, not from the map itself."],bookRef:"Book p. 100; Syllabus 2.1.2"},{id:"sv-2-538",phase:2,topic:"2.1.2",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

Process mapping is the first activity of the [?] phase.`,options:["Analyze","Control","Define","Measure"],answer:3,hint:"Where does the book place detailed mapping in DMAIC?",steps:[{title:"Key idea",body:"The book states that process mapping is the first activity of the Measure phase."},{title:"Apply to the stem",body:"The map then feeds the fishbone, X-Y matrix and FMEA."}],final:"Mapping opens Measure → answer **D**",whyWrong:["Incorrect — Analyze uses the map and data to prove X’s; mapping has already been done by then.","Incorrect — Control updates maps for the new process, but mapping does not start there.","Incorrect — Define uses a high-level SIPOC for scope; detailed mapping opens the next phase.",""],bookRef:"Book p. 99; Syllabus 2.1.2"},{id:"sv-2-539",phase:2,topic:"2.1.2",qtype:"best-action",difficulty:3,stem:"A draft Level 2 map of a refund process has one diamond, **“Refund type?”**, with three exits: Card, Bank transfer and Voucher. What is the BEST way to correct the map?",options:["Keep the diamond, because a decision may have as many exits as needed","Redraw the decision as an activity rectangle","Replace it with two decisions in a row, each with only Yes and No exits","Move the three options into a parallelogram"],answer:2,hint:"Diamond = decision with only Yes/No paths.",steps:[{title:"Key idea",body:"A standard decision diamond has only two exits: Yes and No."},{title:"Apply to the stem",body:"Three outcomes are shown as a chain: “Card?” Yes/No, then “Bank transfer?” Yes/No (No = Voucher)."}],final:"Split into Yes/No decisions → answer **C**",whyWrong:["Incorrect — on the book’s standard symbols a decision has only two paths, Yes and No.","Incorrect — a choice between paths is still a decision; a rectangle is an activity starting with a verb.","","Incorrect — a parallelogram shows data; it cannot route the flow down different paths."],bookRef:"Book p. 101; Syllabus 2.1.2"},{id:"sv-2-540",phase:2,topic:"2.1.2",qtype:"concept",difficulty:1,stem:"Besides process inputs (X’s), what does mapping a process help a team identify about the **customer side** of the process?",options:["The process outputs (Y’s) and the real customer needs","The customer’s credit rating and payment history","The statistical distribution of customer complaints","The customer’s share of total company revenue"],answer:0,hint:"Book p. 100: mapping gives inputs and supplier requirements, and outputs and customer needs.",steps:[{title:"Key idea",body:"The book lists process outputs (Y’s) and real customer needs among the information mapping provides."},{title:"Eliminate look-alikes",body:"The other options are business or statistical data that the map does not show."}],final:"Outputs and real customer needs → answer **A**",whyWrong:["","Incorrect — credit data are business records, not something a process map reveals.","Incorrect — distributions come from data analysis such as histograms, not from the map.","Incorrect — revenue share is a finance figure, unrelated to the process flow."],bookRef:"Book p. 100; Syllabus 2.1.2"}];export{e as items};
